// TH14 v1.00b st07bs::Boss3, Extra 3rd nonspell. Entry294-346; closure Boss3_at348-380.
// Extra reads the source O mask, so only rank4 is declared. Source t0 = phase start + OPENING_BUFFER.
// Native nonspell slot0 timer is 3000 frames; the prepared window adds a 300-frame tail.
const TIME_LIMIT: int = 3424;
const SOURCE_LIMIT: int = 3000;
const OPENING_BUFFER: int = 120;
const TH14_RICE: int = 480; // source type8; synthetic catalog slot, see transcribe/th14/bullet-types.md

// Source Boss3_at EX records: ANIM(a=1) is the birth animation and is omitted by approved policy
// (its -4*speed spawn retreat is kept via sh_dist); BOUNCE(a=1,b=13) bounces off up+left+right;
// SETSPRITE(8,4) is the steady look used from spawn because the birth phase is omitted.
xformdef RICE_BOUNCE {
    // Source wall bits U/D/L/R=1/2/4/8; b=13 -> up+left+right. Target left/right/up/down=1/2/4/8.
    bounce_arm(7, 1);
}
// Source Boss3_at etAim mode10 is a 64-lane ring with three alternating mirrored layers; its
// per-layer angle offsets are not a constant step, so the layers use three ring emitters.
// dist = etDist16 - 4*speed (ANIM retreat); speed is the layer speed of source etSpeed(1.2,1.18).
sub setup_ring(id: int, speed: fx, dist: fx) {
    sh_reset(id);
    sh_sprite(id, TH14_RICE, 4);
    sh_ring(id, 1);
    sh_count(id, 64, 1);
    sh_speed(id, speed, 0fx);
    sh_offset(id, 0fx, 24fx); // source etOffset(0,24)
    sh_dist(id, dist);
    sh_xform(id, RICE_BOUNCE);
}
// Source %A=%RANDRAD, %B=3.883222rad, $C=10000, $D=8; one volley per 130 frames.
// 22 volleys fire before the native 3000-frame interrupt; the next would be frame3001.
async sub src_boss3_at() {
    setup_ring(0, 1.2fx, 11.2fx);   // q=0 speed1.2
    setup_ring(1, 1.18fx, 11.28fx); // q=1 speed1.18
    setup_ring(2, 1.18fx, 11.28fx); // q=2 speed1.18
    var a: int = rand(65536)-32768; // %RANDRAD, -pi..pi in BAM
    var b: int = 40503;             // %B = 3.883222rad
    for i in 0..22 {
        if i == 8 || i == 16 { b = 0-b; } // %B = %B*-1 after each 8-volley group
        // q=0: a+R(i); q=1: a-1deg-R(i), i.e. the same point set as a ring at a-1deg;
        // q=2: a+1deg+R(i). Emission order stays layer-major, lanes ascending.
        sh_angle(0, a as angle, 0deg);
        sh_fire(0);
        sh_angle(1, (a-182) as angle, 0deg);
        sh_fire(1);
        sh_angle(2, (a+182) as angle, 0deg);
        sh_fire(2);
        a = a+b;
        wait(130);
    }
}
async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT;
    // Source entry: clear old velocity/position interpolation, then 60-frame quad-out return to
    // (0,128). The independent card already spawns there, so this is the zero-displacement move.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    // moveLimit(0,128,280,64) is applied per movement tick by the moveRand helper.
    wait(80);
    spawn src_boss3_at();
    wait(120);
    loop {
        if $frame >= until { return; }
        card_move_rand();
        card_wait_until(120, until);
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // Boss context setHitbox(48,48): native ordinary circle uses width*0.5
    set_hurtbox(24fx);  // Boss context setHurtbox(48,48)
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 13300, 0, 0, 0, boss_main); // source lifeSet(2300+11000)
    loop { wait(600); }
}

// TH14 v1.00b Boss3 only. Source moveRand(60,4,1.0) under moveLimit(0,128,280,64).
// int slot0 = next-step count; fx slots0/1 = logical unit vector. The source attack does not read
// these slots, and this card owns them.
// Same per-tick recipe as transcribe/th16/movement.md; only the limit rectangle and the direction
// inner zone change with this card's moveLimit width (280 -> x +-70; height 64 -> y 112..144).
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source normalizes this branch only
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately not normalized before the fabs tests, as in the source.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05rad.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait_until(frames: int, until: int) {
    for i in 0..frames {
        if $frame >= until { return; }
        wait(1);
        card_arm_next_step();
    }
}
